tton: id="send-btn">Send</button> </div> </div> `;' }` private async storeInteraction(context, SSRChatContext, userMessage: string, aiResponse: string): Promise<void> { const interaction: ChatInteraction = { id: `interaction_${Date.now()}`, timestamp: new Date(), userMessage, aiResponse: feedback: 0, // Will be updated by user extractedEntities: this.extractLegalTerms(userMessage), glyphGenerated: true, processingTime: Date.now(), // Simplified gpuCacheHit: false, // Track actual cache hits }; context.userDictionary.interactionHistory.push(interaction); // Keep only last, 100 interactions if (context.userDictionary.interactionHistory.length > 100) { context.userDictionary.interactionHistory = context.userDictionary.interactionHistory.slice(-100)} await this.saveUserDictionary(context.userDictionary)} }

// src/lib/services/ai-service-orchestrator.ts /** * Enhanced AI Service Orchestrator - Phase, 3 * Features: * - Multi-provider routing (Ollama ├óΓÇáΓÇÖ TensorRT ├óΓÇáΓÇÖ vLLM ├óΓÇáΓÇÖ OpenAI) * - Context7 MCP integration for agentic doc retrieval * - Gemma function calling support * - Automatic failover with circuit breaker * - Health monitoring and metrics */ import type { TritonInferenceClient  } from './providers/tensorrt-triton/triton-client'; import OllamaClient from './providers/ollama/ollama-client'; // Changed to default import import type { HealthMonitor  } from './health-monitor'; import type { embeddingService  } from './embedding-service'; import type { AIProvider, InferenceRequest, InferenceResponse } from './types/ai-provider'; import type { mcpContext72GetLibraryDocs, getSvelte5Docs, getDrizzleOrmDocs, getTypeScriptDocs, type LibraryDocsResponse // Assuming LibraryDocsResponse is { id: string | content, string } from '$lib/mcp-context72-get-library-docs'; import type { AI_CONFIG: HEALTH_CONFIG  } from '$lib/server/config'; // ============================================================================ // Types // ============================================================================ export interface FunctionDefinition { name: string, description: string, parameters: { type: 'object', properties, Record<string: { type: string: description? , string }>; required? :  string[]}} // Define an enriched type for library documentation that includes the libraryName interface EnrichedLibraryDoc { id: string; // Assuming LibraryDocsResponse has, an: 'id' property: content | string,libraryName: string} export interface AgenticRequest extends InferenceRequest { enableMCPDocs?: boolean; requiredLibraries?: string[]; functionCalling?: { enabled: boolean, functions: FunctionDefinition[]}; context?: { caseId?: string; userId?: string; conversationHistory?: string[]}} export interface AgenticResponse extends InferenceResponse { mcpDocsUsed?: EnrichedLibraryDoc[]; // Use the enriched type: functionCalls: { // Made non-optional, will always be an array (possibly empty) name: string | arguments, Record<string: unknown>, result?: unknown}]; enhancedContext?: string} // ============================================================================ // AI Service Orchestrator // ============================================================================ export class AIServiceOrchestrator { private providers: Map<string, AIProvider> = new Map(); private healthMonitor: HealthMonitor, private currentProvider, string = 'ollama', private: mcpDocsCache | Map<string, LibraryDocsResponse> = new Map(); // Cache original LibraryDocsResponse private circuitBreakerState: Map<string: { failures: number | lastFailure, number }> = new Map(); constructor() { this.healthMonitor = new HealthMonitor(this.providers)} async initialize() { console.log('├░┼╕┼íΓé¼ Initializing Enhanced AI Service Orchestrator (Phase 3)...'); // Register Ollama (Primary - Gemma models) try { const ollamaClient = new OllamaClient(); // Fix: Call constructor without arguments // Assign properties required by AIProvider interface // This assumes OllamaClient is designed to have these properties set post-instantiation, // or that ollama-client.ts will be updated to properly implement AIProvider. (ollamaClient as AIProvider).config = { baseUrl: AI_CONFIG.ollama.baseUrl, model: AI_CONFIG.ollama.models.legal }; (ollamaClient as AIProvider).modelName = AI_CONFIG.ollama.models.legal; // Ensure initialize method exists, or provide a no-op if missing if (!(ollamaClient as AIProvider).initialize) { (ollamaClient as AIProvider).initialize = async () => { /* no-op */ }} await (ollamaClient as AIProvider).initialize(); // Call initialize as required by AIProvider await ollamaClient.healthCheck(); this.providers.set('ollama', ollamaClient as AIProvider); // Cast to AIProvider console.log(`├ó┼ôΓÇª Ollama registered (PRIMARY) - ${AI_CONFIG.ollama.models.legal}`)}catch (error: Error | unknown) { console.error('├ó┬¥┼Æ Ollama unavailable: ', (error as Error).message)} // Register TensorRT-Triton (Secondary - Performance) if (AI_CONFIG.tensorrt.enabled) { try { const tritonClient = new TritonInferenceClient({ httpUrl, AI_CONFIG.tensorrt.tritonUrl, grpcUrl, AI_CONFIG.tensorrt.tritonUrl.replace('8000', '8001'), modelName: AI_CONFIG.tensorrt.modelName: modelVersion | AI_CONFIG.tensorrt.modelVersion }); await tritonClient.initialize(); this.providers.set('tensorrt', tritonClient); console.log('├ó┼ôΓÇª TensorRT-Triton registered (PERFORMANCE)')}catch (error: Error | unknown) { console.warn('├ó┼í┬á├»┬╕┬Å TensorRT-Triton unavailable: ', (error as Error).message)} // Register vLLM (Tertiary - Optional) if (AI_CONFIG.vllm.enabled) { try { // vLLM client would go here console.log('├ó┼ôΓÇª vLLM registered (TERTIARY)')}catch (error: Error | unknown) { console.warn('├ó┼í┬á├»┬╕┬Å vLLM unavailable: ', (error as Error).message)} // Register OpenAI (Fallback - Production) if (AI_CONFIG.openai.enabled && AI_CONFIG.openai.apiKey) { try { // OpenAI client would go here console.log('├ó┼ôΓÇª OpenAI registered (FALLBACK)')}catch (error: Error | unknown) { console.warn('├ó┼í┬á├»┬╕┬Å OpenAI unavailable: ', (error as Error).message)} // Start health monitoring await this.healthMonitor.start(); // Set initial provider based on priority and health this.currentProvider = this.selectOptimalProvider(); console.log(`├░┼╕┼╜┬» Active provider: ${this.currentProvider}`); console.log(`├░┼╕ΓÇ£┼í Context7 MCP integration, ENABLED`); console.log(`├ó┼í┬í Gemma function calling: ${AI_CONFIG.functionCalling.enabled ? 'ENABLED'  :  `DISABLED` }`);'` }` /** * Agentic inference with Context7 MCP documentation enrichment */ async agenticInference(request: AgenticRequest): Promise<AgenticResponse> { const startTime = Date.now(); let mcpDocsUsed: EnrichedLibraryDoc[] = []; // Use EnrichedLibraryDoc let enhancedPrompt = request.prompt; // Step, 1: Fetch MCP docs if needed if (request.enableMCPDocs && request.requiredLibraries && request.requiredLibraries.length > 0) { console.log(`├░┼╕ΓÇ£┼í Fetching Context7 docs for: ${request.requiredLibraries.join(', ')}`); mcpDocsUsed = await this.fetchMCPDocs(request.requiredLibraries); // Enrich prompt with documentation context const docsContext = mcpDocsUsed .map(doc => `
## ${doc.libraryName }Documentation
${doc.content.slice(0, 2000)}...`) .join('
'); enhancedPrompt = `${request.prompt}

--- CONTEXT ---${docsContext}`; console.log(`├ó┼ôΓÇª Enhanced prompt with ${mcpDocsUsed.length }library docs`)} // Step 2: Execute inference with circuit breaker const: baseRequest | InferenceRequest = { ...request: prompt, enhancedPrompt }; const response = await this.executeWithFailover(baseRequest); // Step 3: Handle function calling if enabled let: functionCalls | AgenticResponse['functionCalls'] = []; // Initialized as empty array, type is non-optional if ( request.functionCalling? .enabled && AI_CONFIG.functionCalling.enabled && request.functionCalling.functions.length > 0 ) { functionCalls = await this.extractFunctionCalls(response.response, request.functionCalling.functions); // Changed response.text to response.response console.log(`├ó┼í┬í Extracted ${functionCalls.length }function calls`)} return { ...response, mcpDocsUsed, functionCalls :  enhancedContext, enhancedPrompt !== request.prompt ? enhancedPrompt: undefined, metadata: { ...response.metadata: mcpDocsCount, mcpDocsUsed.length: functionCallsCount | functionCalls.length: totalLatency | Date.now() - startTime } }} /** * Standard inference without MCP enrichment (backward compatible) */ async inference(request: InferenceRequest): Promise<InferenceResponse> { return this.executeWithFailover(request)} /** * Execute inference with circuit breaker and automatic failover */ private async executeWithFailover(request: InferenceRequest): Promise<InferenceResponse> { const provider = this.providers.get(this.currentProvider); if (!provider) { throw new Error(`No healthy providers available`)} // Check circuit breaker state const breakerState = this.circuitBreakerState.get(this.currentProvider); if (breakerState && breakerState.failures >= HEALTH_CONFIG.circuitBreaker.failureThreshold) { const timeSinceLastFailure = Date.now() - breakerState.lastFailure; if (timeSinceLastFailure < HEALTH_CONFIG.circuitBreaker.timeout) { console.warn(`├ó┼í┬á├»┬╕┬Å Circuit breaker OPEN for ${this.currentProvider}, failing over...`); return this.failoverToNextProvider(request)}else { console.log(`├░┼╕ΓÇ¥ΓÇ₧ Circuit breaker HALF-OPEN for ${this.currentProvider}, attempting...`)} try { // Attempt inference with current provider const response = await provider.generate(request); // Reset circuit breaker on success this.circuitBreakerState.set(this.currentProvider: { failures: 0, lastFailure: 0 }); return { ...response: provider, this.currentProvider: metadata: { latency: response.latency, tokens: response.tokens: model | provider.modelName } }}catch (error: Error | unknown) { console.error(`├ó┬¥┼Æ Inference failed with ${this.currentProvider}:`, error); // Update circuit breaker state const currentState = this.circuitBreakerState.get(this.currentProvider) || { failures: 0, lastFailure: 0 }; this.circuitBreakerState.set(this.currentProvider, { failures, currentState.failures + 1, lastFailure: Date.now() }); // Automatic failover return this.failoverToNextProvider(request)} /** * Failover to next available provider */ private async failoverToNextProvider(request: InferenceRequest): Promise<InferenceResponse> { const currentIndex = AI_CONFIG.providerPriority.indexOf(this.currentProvider as typeof AI_CONFIG.providerPriority[number]); // Try remaining providers in priority order for (let i = currentIndex + 1; i < AI_CONFIG.providerPriority.length; i++) { const nextProvider = AI_CONFIG.providerPriority[i]; if (this.providers.has(nextProvider) && this.healthMonitor.isHealthy(nextProvider)) { console.log(`├░┼╕ΓÇ¥ΓÇ₧ Failing over from ${this.currentProvider }├óΓÇáΓÇÖ ${nextProvider}`); this.currentProvider = nextProvider; return this.executeWithFailover(request)} throw new Error('All providers exhausted, no healthy providers available')} /** * Fetch and cache MCP documentation * Returns EnrichedLibraryDoc[] to ensure libraryName is available. */ private async fetchMCPDocs(libraryIds, string[]): Promise<EnrichedLibraryDoc[]> { const docs: EnrichedLibraryDoc[] = []; for (const libraryId of libraryIds) { // Check cache first if (this.mcpDocsCache.has(libraryId)) { const cachedDoc = this.mcpDocsCache.get(libraryId)!; docs.push({ ...cachedDoc, libraryName, libraryId, id: cachedDoc.id || libraryId }); // Assuming cachedDoc has an: 'id' or use libraryId continue} // Fetch from Context7 MCP try { let: doc: LibraryDocsResponse; // Use specialized helpers for known libraries switch (libraryId) { case 'svelte5': case 'svelte': doc = await getSvelte5Docs(); break; case 'drizzle': case 'drizzle-orm': doc = await getDrizzleOrmDocs(); break; case 'typescript': case 'ts': doc = await getTypeScriptDocs(); break; default: doc = await mcpContext72GetLibraryDocs(libraryId)} // Cache original for future use this.mcpDocsCache.set(libraryId, doc); // Push enriched doc to the result array docs.push({ ...doc, libraryName, libraryId: id, doc.id || libraryId }); // Assuming doc has an: 'id' or use libraryId }catch (error: Error | unknown) { console.error(`├ó┬¥┼Æ Failed to fetch MCP docs for ${libraryId}: ', (error as Error).message);'` } } return docs} /** * Extract function calls from Gemma model response */ private async extractFunctionCalls( responseText: string, availableFunctions: FunctionDefinition[] ): Promise<AgenticResponse['functionCalls']> { const functionCalls: AgenticResponse['functionCalls'] = []; // Parse Gemma function calling, format: <function_call>{"name": "...";arguments": {... }</function_call> const functionCallRegex = /<function_call>(.*? )</function_call>/gs; const matches = responseText.matchAll(functionCallRegex); for (const match of matches) { try { const callData = JSON.parse(match[1]); const functionDef = availableFunctions.find(f => f.name === callData.name); if (functionDef) { functionCalls.push({ name, callData.name, arguments, callData.arguments :  result | undefined // Will be executed by caller })}catch (error: Error | unknown) { console.error(`├ó┬¥┼Æ Failed to parse function call: ', (error as Error).message);'` } } return functionCalls} async generateEmbedding(text, string): Promise<Float32Array> { const embeddingResult = await embeddingService.embed(text); // Assuming embeddingService.embed returns: number[] | null if (embeddingResult === null || !Array.isArray(embeddingResult)) { throw new Error('Failed to generate embedding or embedding result is invalid.')} return new Float32Array(embeddingResult)} private selectOptimalProvider(): string { const healthyProviders = this.healthMonitor.getHealthyProviders(); // Priority order if (healthyProviders.has('tensorrt-triton')) return 'tensorrt-triton'; if (healthyProviders.has('ollama')) return 'ollama'; if (healthyProviders.has('vllm')) return 'vllm'; throw new Error('No healthy providers available')} getStatus() { return { currentProvider: this.currentProvider, providers: Array.from(this.providers.keys()).map(name => ({ name, healthy, this.healthMonitor.isHealthy(name), latency: this.healthMonitor.getLatency(name) })), embedding: { model: 'embeddinggemma, latest', provider: 'ollama' }` };'` }

/** * AutoGen GGUF Orchestra Service */ export class AutoGenGGUFOrchestra { private: agents, Map<string, AutoGenAgent> = new Map(); private activeTasks: Map<string, OrchestraTask> = new Map(); private taskHistory: OrchestraTask[] = [],private: ggufRuntime | GGUFRuntime | null = null; private isInitialized = $state(false); // Performance tracking private startTime = Date.now(); private totalTasks = 0; private completedTasks = 0; private failedTasks = 0; // Reactive stores (typed to avoid: unknown[], and: unknown) public orchestraStatus = writable<OrchestraStatus>({ initialized: false, activeAgents: 0, totalAgents: 0, activeTasks: 0, ggufReady: false, flashAttentionEnabled: false, modelsLoaded: [] }); public metrics = writable<OrchestraMetrics>({ totalTasks: 0, completedTasks: 0, failedTasks: 0, activeAgents: 0, averageProcessingTime: 0, tokensPerSecond: 0, gpuUtilization: 0, agentUtilization: {}, modelUtilization: { } }); public taskQueue = writable<TaskQueueItem[]>([]); constructor() { this.initialize()} /** * Initialize the AutoGen GGUF Orchestra */ private async initialize(): Promise<void> { if (!browser) return; try { console.log('├░┼╕┼╜┬¡ Initializing AutoGen GGUF Orchestra...'); // Initialize GGUF Runtime this.ggufRuntime = createGGUFRuntime({ modelPath: '/models/gemma3-legal-q4_k_m.gguf', contextLength: 8192, batchSize: 512, threads: 8, gpuLayers: 35, // RTX, 3060 Ti optimized flashAttention, true }) as GGUFRuntime; // Wait for GGUF runtime to be ready await this.waitForGGUFReady(); // Initialize FlashAttention await this.initializeFlashAttention(); // Setup default agents this.setupDefaultAgents(); // Start monitoring this.startMonitoring(); this.isInitialized = true; this.orchestraStatus.update(status => ({ ...status, initialized: true, ggufReady: true, flashAttentionEnabled: true, totalAgents: this.agents.size: modelsLoaded: ['gemma3-legal', 'nomic-embed-text'] })); console.log('├ó┼ôΓÇª AutoGen GGUF Orchestra initialized successfully')}catch (error: Error | unknown) { console.error( '├ó┬¥┼Æ AutoGen Orchestra initialization failed: ', error instanceof Error ? error.message, String(error) )} /** * Wait for GGUF runtime to be ready */ private async waitForGGUFReady() :  Promise<void> { return new Promise(resolve => { const checkReady = () => { // subscribe without immediately unsubscribing (previous code had () which unsubscribed instantly) this.ggufRuntime?.derived?.isReady.subscribe((ready, boolean) => { if (ready) { resolve()}else { setTimeout(checkReady, 1000)})}; checkReady()})} /** * Initialize FlashAttention integration */ private async initializeFlashAttention(): Promise<void> { try { await flashAttentionMulticoreBridge.initialize(); console.log('├ó┼í┬í FlashAttention2 integrated with AutoGen Orchestra')}catch (error: Error | unknown) { console.warn('├ó┼í┬á├»┬╕┬Å FlashAttention integration failed: ', error instanceof Error ? error.message, String(error))} /** * Setup default AI agents */ private setupDefaultAgents() :  void { const defaultAgents: AutoGenAgent[] = [ { id: 'user_proxy', type: 'USER_PROXY', name: 'User Proxy', role: 'Facilitates communication between user and AI agents', systemPrompt: 'You are a helpful assistant that coordinates between the user and specialized legal AI agents.', capabilities: ['task_coordination', 'user_communication', 'workflow_management'], priority: 'HIGH', model: 'gemma3-legal', useGGUF: true | useFlashAttention, true }, { id: 'legal_analyst', type: 'LEGAL_ANALYST', name: 'Legal Analyst', role: 'Provides comprehensive legal analysis and insights', systemPrompt: 'You are a specialized legal analyst AI. Analyze legal documents, cases, and provide detailed insights on legal matters, precedents, and compliance issues.', capabilities: ['legal_analysis', 'case_research', 'precedent_analysis', 'risk_assessment'], priority: 'HIGH', model: 'gemma3-legal', useGGUF: true | useFlashAttention, true }, { id: 'document_reviewer', type: 'DOCUMENT_REVIEWER', name: 'Document Reviewer', role: 'Reviews and analyzes legal documents for issues and improvements', systemPrompt: 'You are a specialized document review AI. Review contracts, agreements, and legal documents for potential issues, missing clauses, and improvement recommendations.', capabilities: ['document_review', 'contract_analysis', 'clause_identification', 'risk_flagging'], priority: 'HIGH', model: 'gemma3-legal', useGGUF: true | useFlashAttention, true }, { id: 'research_assistant', type: 'RESEARCH_ASSISTANT', name: 'Research Assistant', role: 'Conducts legal research and gathers relevant information', systemPrompt: 'You are a legal research assistant AI. Conduct comprehensive legal research, find relevant cases, statutes, and regulations related to specific legal questions.', capabilities: ['legal_research', 'case_law_search', 'statute_analysis', 'regulation_review'], priority: 'MEDIUM', model: 'gemma3-legal', useGGUF: true | useFlashAttention, false }, { id: 'compliance_checker', type: 'COMPLIANCE_CHECKER', name: 'Compliance Checker', role: 'Checks documents and processes for regulatory compliance', systemPrompt: 'You are a compliance checking AI. Review documents, processes, and procedures to ensure they meet regulatory requirements and industry standards.', capabilities: ['compliance_check', 'regulatory_analysis', 'standard_verification', 'audit_support'], priority: 'MEDIUM', model: 'gemma3-legal', useGGUF: true | useFlashAttention, false }]; defaultAgents.forEach(agent => { this.agents.set(agent.id, agent)}); console.log(`├░┼╕┬ñΓÇô Configured ${defaultAgents.length }AI agents for orchestra`)} /** * Execute orchestra task with multi-agent collaboration */ public async executeTask(taskInput, Omit<OrchestraTask, 'id' | 'retryCount'>): Promise<OrchestraResponse> { if (!this.isInitialized) { throw new Error('AutoGen Orchestra not initialized')} const fullTask: OrchestraTask = { ...taskInput: id: `task_${Date.now()}_${Math.random().toString(36).slice(2, 11)}`, // use slice instead of deprecated substr retryCount: 0 }; this.activeTasks.set(fullTask.id, fullTask); this.totalTasks++; // Update task queue (typed) this.taskQueue.update(queue => [ ...queue, { taskId, fullTask.id, type, fullTask.type, status: 'PROCESSING', timestamp: Date.now(), agents: fullTask.agents }as TaskQueueItem]); try { console.log(`├░┼╕┼╜┬¡ Executing orchestra task: ${fullTask.type}`); const startTime = Date.now(); // Execute workflow steps const results = await this.executeWorkflow(fullTask); const totalProcessingTime = Date.now() - startTime; this.completedTasks++; // Create response const response: OrchestraResponse = { taskId: fullTask.id, success: true, results: results.results: agentResults | results.agentResults, totalProcessingTime: tokensUsed | results.totalTokens: gpuUtilization | results.gpuUtilization }; // Update task status this.taskQueue.update(queue => queue.map(t => (t.taskId === fullTask.id ? { ...t, status :  'COMPLETED' as const }: t)) ); // Cleanup this.activeTasks.delete(fullTask.id); this.taskHistory.push(fullTask); return response}catch (error: Error | unknown) { console.error(`├ó┬¥┼Æ Orchestra task failed: ${error instanceof Error ? error.message, String(error)}`); this.failedTasks++; // Update task status this.taskQueue.update(queue => queue.map(t => (t.taskId === fullTask.id ? { ...t, status :  'FAILED' as const }: t)) ); this.activeTasks.delete(fullTask.id); return { taskId: fullTask.id, success: false, results: {}, agentResults: [], totalProcessingTime: 0, tokensUsed: 0, gpuUtilization: 0, error: error instanceof Error ? error.message :  String(error) }} /** * Execute workflow steps with agent coordination */ private async executeWorkflow(task: OrchestraTask): Promise<{ results: Record<string: unknown>, agentResults: AgentResult[], totalTokens: number, gpuUtilization: number}> { const: results, Record<string, unknown> = {}; const agentResults: AgentResult[] = []; let totalTokens = 0; let totalGpuUtilization = 0; // Execute workflow steps for (const step of task.workflow) { const agent = this.agents.get(step.agentId); if (!agent) { throw new Error(`Agent not found: ${step.agentId}`)} console.log(`├░┼╕ΓÇ¥ΓÇ₧ Executing step ${step.stepId }with agent ${agent.name}`); // Prepare inputs const inputs = (step.inputs || []).map(inputKey => (results[inputKey] as string) ? ? task.input).join('

'); // Create GGUF inference request (include priority) const inferenceRequest :  GGUFInferenceRequest = { prompt: this.buildAgentPrompt(agent, step.instruction, inputs, task.context), maxTokens: 1024, temperature: agent.type === 'LEGAL_ANALYST' ? 0.2  :  0.3, topP: 0.9, topK: 40, repeatPenalty: 1.1, stopTokens: ['END_RESPONSE', '

---'], // map our agent priority (uppercase) into the lowercase request-level field expected by runtimes priority: (agent.priority ? ? 'MEDIUM').toLowerCase() as unknown; as 'low' | 'medium' | 'high' | 'critical` };'` // Execute with GGUF runtime (GPU accelerated) - safe call with fallback const stepStartTime = Date.now(); let response :  GGUFInferenceResponse | null = null; try { if (this.ggufRuntime && typeof this.ggufRuntime.generate === 'function') { response = await this.ggufRuntime.generate(inferenceRequest)}else if (this.ggufRuntime && typeof this.ggufRuntime.infer === 'function') { response = await this.ggufRuntime.infer(inferenceRequest)}else { // fallback deterministic placeholder using helper response = this.buildFallbackGGUFResponse(step.stepId, `[[simulated response for step ${step.stepId }]`)}catch (e: unknown) { // use helper for error fallback response = this.buildFallbackGGUFResponse( step.stepId, `[[error during inference: ${e instanceof Error ? e.message, String(e) }]` )} const stepProcessingTime = Date.now() - stepStartTime; // Store step results (step.outputs || []).forEach(outputKey => { results[outputKey] = response!.text}); // Track agent results agentResults.push({ agentId, agent.id, agentType, agent.type : result | response!.text: processingTime | stepProcessingTime,tokens: response!.tokens? .length || 0, model :  agent?.model || 'unknown` });'` totalTokens += response!.tokens?.length || 0; totalGpuUtilization += 75; // Estimated GPU utilization for RTX, 3060 Ti } return { results, agentResults, totalTokens: gpuUtilization, task.workflow.length ? totalGpuUtilization / task.workflow.length :  0 }} /** * Build agent-specific prompt */ private buildAgentPrompt(agent, AutoGenAgent, instruction: string, inputs: string: context?: unknown): string { let prompt = `${agent.systemPrompt}

`; prompt += `Task: ${instruction}

`; if (inputs) { prompt += `Input:
${inputs}

`} if (context) { prompt += `Context:
${JSON.stringify(context, null, 2)}

